def run(name,filter):
 start=time.monotonic();log=out/(name+'.log')
 with log.open('w') as f:
  p=subprocess.run(['xcrun','swift','test','--filter',filter],cwd=root,env=env,stdout=f,stderr=subprocess.STDOUT,timeout=300)
 lines=log.read_text(errors='replace').splitlines();assertions=[x for x in lines if ': error:' in x and ('XCTAssert' in x or 'failed -' in x)]
 invalid_markers=[v for v in ['emit-module command failed','compile command failed','exited with unexpected signal','fatal error:','program crashed:','assertion failed:'] if v in '\n'.join(lines).lower()]
 r={'invalid_markers':invalid_markers,'name':name,'exit':p.returncode,'seconds':round(time.monotonic()-start,2),'assertion_count':len(assertions),'assertions':assertions[:18]};records.append(r);(out/'partial-results.json').write_text(json.dumps(records,indent=2));print(json.dumps(r),flush=True);return r
baseline='RuntimeModuleIntentTests|RuntimeHostInteractiveTests|RuntimeModuleLifecycleModelTests|PhysicalLifecycleTests|RuntimePhysicalOrderingTests'
assert run('baseline',baseline)['exit']==0,'baseline failed before mutation'
originals={}
for name,path,old,new,filter in mutants:
 source=root/path;original=source.read_bytes();originals[path]=hashlib.sha256(original).hexdigest();assert original.count(old.encode())==1,(name,'needle',original.count(old.encode()))
 modified=original.replace(old.encode(),new.encode())
 try:
  source.write_bytes(modified);r=run(name,filter)
 finally:
  assert source.read_bytes()==modified,'source changed during mutation'
  source.write_bytes(original)
 assert r['exit']==1 and r['assertion_count']>0 and not r['invalid_markers'],name+' did not fail an intended assertion'
assert run('restored',baseline)['exit']==0
summary={'head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'test_sha256':{str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for p in (root/'Tests/ConduitTests').glob('*Tests.swift')},'source_sha256':originals,'restored_exactly':all(hashlib.sha256((root/k).read_bytes()).hexdigest()==v for k,v in originals.items()),'checks':records}
(out/'results.json').write_text(json.dumps(summary,indent=2)+'\n');print(str(out),flush=True)
